response1 = client.responses.create(
    model="gpt-5-nano",
    input="Solve 17 * 24, then explain briefly.",
    reasoning={
        "effort": "low",
        "summary": "auto" # capture reasoning summary
    }
)

print("Answer:")
print(response1.output_text)

print("\nReasoning summary:")
for item in response1.output:
    if getattr(item, "type", None) == "reasoning":
        for s in getattr(item, "summary", []):
            print(getattr(s, "text", s))

